# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">DOĞADA KARBON: KARBONUN BAĞ YAPMA ÖZELLİĞİ VE DOĞAL ALLOTROPLARI</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Karbon Atomu (₆C: 2-4)</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Grup / Periyot:</tspan> 2. Periyot, 4A (14.)</text>\n  <text x="32" y="112" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Değerlik Elektron Sayısı:</tspan> 4</text>\n  <text x="32" y="132" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Kovalent Bağ Kapasitesi:</tspan> 4 bağ</text>\n  <text x="40" y="148" font-size="10" fill="#78350f">(Tekli C-C, ikili C=C, üçlü C≡C)</text>\n  <text x="32" y="170" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Çok Bileşik Oluşturma Nedeni:</tspan></text>\n  <text x="40" y="186" font-size="10" fill="#78350f">C-C bağ enerjisinin yüksek olması;</text>\n  <text x="40" y="202" font-size="10" fill="#78350f">düz, dallanmış ve halkalı sağlam</text>\n  <text x="40" y="218" font-size="10" font-weight="bold" fill="#b45309">zincirler (katenasyon) kurabilmesi.</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Elmas (Doğal Allotrop)</text>\n  <text x="257" y="92" font-size="10.5" fill="#1e3a8a">• Her C atomu çevresindeki <tspan font-weight="bold">4 C</tspan></text>\n  <text x="265" y="108" font-size="10.5" fill="#1e3a8a">atomuna güçlü sigma bağlarıyla</text>\n  <text x="265" y="124" font-size="10.5" fill="#1e3a8a">bağlanarak <tspan font-weight="bold">düzgün dörtyüzlü</tspan></text>\n  <text x="265" y="140" font-size="10.5" fill="#1e3a8a">geometri oluşturur (<tspan font-weight="bold">sp³</tspan>).</text>\n  <text x="257" y="162" font-size="10.5" fill="#1e3a8a">• Bilinen <tspan font-weight="bold">en sert</tspan> doğal maddedir.</text>\n  <text x="257" y="182" font-size="10.5" font-weight="bold" fill="#b91c1c">• Elektriği İLETMEZ, ancak ısıyı</text>\n  <text x="265" y="198" font-size="10.5" font-weight="bold" fill="#1d4ed8">çok iyi iletir.</text>\n  <text x="257" y="218" font-size="10" fill="#1e3a8a">• Cam kesici ve matkap uçlarında.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Grafit (Doğal Allotrop)</text>\n  <text x="482" y="92" font-size="10.5" fill="#14532d">• Her C atomu aynı düzlemdeki <tspan font-weight="bold">3 C</tspan></text>\n  <text x="490" y="108" font-size="10.5" fill="#14532d">atomuna bağlanarak <tspan font-weight="bold">altıgen halkalı</tspan></text>\n  <text x="490" y="124" font-size="10.5" fill="#14532d"><tspan font-weight="bold">tabakalar</tspan> oluşturur (<tspan font-weight="bold">sp²</tspan>).</text>\n  <text x="482" y="146" font-size="10.5" fill="#14532d">• Tabakalar arasında zayıf <tspan font-weight="bold">Van der</tspan></text>\n  <text x="490" y="162" font-size="10.5" fill="#14532d"><tspan font-weight="bold">Waals</tspan> bağları ve serbest <tspan font-weight="bold">pi (π)</tspan></text>\n  <text x="490" y="178" font-size="10.5" fill="#14532d">elektronları bulunur.</text>\n  <text x="482" y="198" font-size="10.5" font-weight="bold" fill="#15803d">• Yumuşaktır, ısı ve elektriği İLETİR.</text>\n  <text x="482" y="218" font-size="10" fill="#14532d">• Kurşun kalem ucu, kuru pil, döküm.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KARBONUN YAPAY ALLOTROPLARI: FULLEREN, GRAFEN VE NANOTÜP</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">1. Fulleren (C₆₀ Top/Küre)</text>\n  <text x="32" y="92" font-size="10.5" fill="#581c87">• Grafitten yapay olarak elde edilen</text>\n  <text x="40" y="108" font-size="10.5" fill="#581c87"><tspan font-weight="bold">top, tüp, çubuk ve halka</tspan> şeklindeki</text>\n  <text x="40" y="124" font-size="10.5" fill="#581c87">nanoboyutlu allotroptur.</text>\n  <text x="32" y="146" font-size="10.5" fill="#581c87">• Tabakalarda <tspan font-weight="bold">beşgen, altıgen ve</tspan></text>\n  <text x="40" y="162" font-size="10.5" fill="#581c87"><tspan font-weight="bold">yedigen</tspan> karbon halkaları bulunur.</text>\n  <text x="32" y="184" font-size="10.5" fill="#581c87">• Çok küçük sıcaklıkta bile elektrik</text>\n  <text x="40" y="200" font-size="10.5" font-weight="bold" fill="#7e22ce">iletkenliği (süper iletken) yüksektir.</text>\n  <text x="32" y="220" font-size="10" fill="#581c87">• Güneş pilleri, kurşungeçirmez yelek.</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. Grafen (2 Boyutlu Bal Peteği)</text>\n  <text x="257" y="92" font-size="10.5" fill="#1e3a8a">• Grafitin <tspan font-weight="bold">tek bir atom kalınlığındaki</tspan></text>\n  <text x="265" y="108" font-size="10.5" fill="#1e3a8a">iki boyutlu (2B) altıgen bal peteği</text>\n  <text x="265" y="124" font-size="10.5" fill="#1e3a8a">örgü tabakasıdır.</text>\n  <text x="257" y="146" font-size="10.5" fill="#1e3a8a">• Saydam ve esnektir; <tspan font-weight="bold">çelikten 6 kat</tspan></text>\n  <text x="265" y="162" font-size="10.5" fill="#1e3a8a"><tspan font-weight="bold">hafif, 200 kat daha sağlamdır</tspan>.</text>\n  <text x="257" y="184" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Isı ve elektriği bakır ve elmastan</text>\n  <text x="265" y="200" font-size="10.5" font-weight="bold" fill="#1d4ed8">çok daha hızlı iletir.</text>\n  <text x="257" y="220" font-size="10" fill="#1e3a8a">• Katlanabilir ekran, süper kapasitör.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. Karbon Nanotüp</text>\n  <text x="482" y="92" font-size="10.5" fill="#14532d">• Grafen tabakalarının (veya grafitten)</text>\n  <text x="490" y="108" font-size="10.5" fill="#14532d"><tspan font-weight="bold">silindirik boru (tüp)</tspan> şeklinde</text>\n  <text x="490" y="124" font-size="10.5" fill="#14532d">kıvrılmasıyla oluşan yapay allotroptur.</text>\n  <text x="482" y="146" font-size="10.5" fill="#14532d">• Çapları birkaç nanometre, boyları</text>\n  <text x="490" y="162" font-size="10.5" fill="#14532d">milimetre düzeyinde olabilir.</text>\n  <text x="482" y="184" font-size="10.5" font-weight="bold" fill="#15803d">• Yüksek mukavemet, esneklik ve</text>\n  <text x="490" y="200" font-size="10.5" font-weight="bold" fill="#15803d">yarı iletken / iletken özellik taşır.</text>\n  <text x="482" y="220" font-size="10" fill="#14532d">• Nanoteknoloji, biyosensör, uzay.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KARBON ALLOTROPLARININ KARŞILAŞTIRMALI ÖZET TABLOSU</text>\n  <rect x="20" y="45" width="660" height="198" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.8"/>\n  <rect x="20" y="45" width="660" height="34" rx="8" fill="#1e293b"/>\n  <text x="95" y="67" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">Allotrop</text>\n  <text x="225" y="67" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">Türü ve Hibritleşme</text>\n  <text x="385" y="67" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">Geometrik Yapı</text>\n  <text x="570" y="67" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">Elektrik İletkenliği</text>\n  <line x1="20" y1="118" x2="680" y2="118" stroke="#cbd5e1"/>\n  <text x="95" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Elmas</text>\n  <text x="225" y="102" text-anchor="middle" font-size="10.5" fill="#334155">Doğal — sp³</text>\n  <text x="385" y="102" text-anchor="middle" font-size="10.5" fill="#334155">3B Düzgün Dörtyüzlü Ağ</text>\n  <text x="570" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">İletmez (Yalnız ısıyı iletir)</text>\n  <line x1="20" y1="158" x2="680" y2="158" stroke="#cbd5e1"/>\n  <text x="95" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Grafit</text>\n  <text x="225" y="142" text-anchor="middle" font-size="10.5" fill="#334155">Doğal — sp²</text>\n  <text x="385" y="142" text-anchor="middle" font-size="10.5" fill="#334155">Altıgen Halkalı Tabakalar</text>\n  <text x="570" y="142" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#16a34a">İletir (Serbest π elektronları)</text>\n  <line x1="20" y1="198" x2="680" y2="198" stroke="#cbd5e1"/>\n  <text x="95" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Fulleren</text>\n  <text x="225" y="182" text-anchor="middle" font-size="10.5" fill="#334155">Yapay — sp² (ağırlıklı)</text>\n  <text x="385" y="182" text-anchor="middle" font-size="10.5" fill="#334155">Top, Tüp, Halka (5-6-7\'li)</text>\n  <text x="570" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#16a34a">Süper İletken Özellik Gösterir</text>\n  <text x="95" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Grafen / Nanotüp</text>\n  <text x="225" y="224" text-anchor="middle" font-size="10.5" fill="#334155">Yapay — sp²</text>\n  <text x="385" y="224" text-anchor="middle" font-size="10.5" fill="#334155">2B Bal Peteği / Silindir Tüp</text>\n  <text x="570" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#16a34a">Çok Yüksek İletkenlik</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
